import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize, SkinToneType } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `Check ID Photo compliance. Output JSON. 
            Requirements: Face front-facing, eyes open, mouth closed, sufficient lighting.
            'instruction': Vietnamese command (e.g. "Mở mắt to", "Nhìn thẳng").
            If perfect: "Giữ nguyên".` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    const errorStr = JSON.stringify(error, null, 2);
    console.error("AI Analysis Error", errorStr);

    const isQuotaError = 
      error.status === 429 || 
      error.status === 'RESOURCE_EXHAUSTED' || 
      (error.error && error.error.code === 429) ||
      (error.error && error.error.status === 'RESOURCE_EXHAUSTED') ||
      (error.message && (error.message.includes('429') || error.message.includes('Quota') || error.message.includes('Limit'))) ||
      errorStr.includes('"code":429') || 
      errorStr.includes('"status":429') ||
      errorStr.includes('RESOURCE_EXHAUSTED') ||
      (error.name === 'ApiError' && error.status === 429);

    if (isQuotaError) {
       return { 
        isCompliant: true, 
        status: 'VALID', 
        feedback: 'AI_LIMIT', 
        instruction: 'Hết lượt AI. Chuyển thủ công.', 
        faceDetected: true 
      };
    }

    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Offline Mode', 
      instruction: 'Chụp thủ công', 
      faceDetected: true 
    };
  }
};

/**
 * Processes the ID photo using AI in a SINGLE BATCH.
 * Strictly preserves biometrics.
 * UPDATED: Returns TRANSPARENT PNG (Alpha Channel) for background removal.
 * Background color compositing is now handled by the Frontend.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings, 
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // --- 1. BACKGROUND PROMPT (TRANSPARENT ALPHA ONLY) ---
  // We do NOT bake the color here anymore (except for Original). 
  // We ask for a transparent cutout so the UI can swap colors instantly.
  let bgInstruction = "";

  if (bgType === BackgroundType.ORIGINAL) {
    bgInstruction = "TASK 1 (Background): Keep original background exactly as is. Do not change transparency.";
  } else {
    // FORCE TRANSPARENCY
    bgInstruction = `TASK 1 (Background): Remove the background completely. 
    - Output MUST be a PNG with a TRANSPARENT Alpha Channel (Alpha = 0).
    - Do NOT replace with white, blue, or gray.
    - Hair strands must be segmented delicately with soft alpha matting.
    - No halo artifacts around the head.`;
  }

  // --- 2. CLOTHING PROMPT ---
  let clothingInstruction = "TASK 2 (Clothing): Keep original clothing.";
  if (clothingPrompt) {
    clothingInstruction = `TASK 2 (Clothing): Replace outfit with: "${clothingPrompt}". 
    - Ensure the collar fits the neck perfectly. 
    - Adjust lighting on clothes to match the face.
    - Style: Professional ID Photo.`;
  }

  // --- 3. BEAUTY / RETOUCH PROMPT (VERY NATURAL) ---
  let beautyInstruction = "TASK 3 (Retouch): No makeup changes.";
  const retouchSteps = [];

  // Blemishes
  if (beautySettings.removeBlemishes) {
    retouchSteps.push("Subtly reduce temporary acne visibility. CRITICAL: KEEP MOLES (nốt ruồi) AND SCARS (sẹo) visible as they are biometric identifiers.");
  }

  // Smooth Skin (Dynamic AI Smoothing)
  if (beautySettings.smoothSkin > 0) {
    const val = beautySettings.smoothSkin;
    let skinPrompt = "";

    if (val <= 30) {
        // Level 1: Natural (Micro-retouch)
        skinPrompt = "Level 1 Skin Retouch: Remove oiliness/shine and redness only. Keep 100% natural skin texture, pores, and fine lines. Do NOT blur.";
    } else if (val <= 70) {
        // Level 2: Portrait (Soft Glam)
        skinPrompt = "Level 2 Skin Retouch: Soften pore visibility and fine wrinkles. Even out skin tone. Maintain natural skin grain structure. Avoid plastic look.";
    } else {
        // Level 3: Polished (High End)
        skinPrompt = "Level 3 Skin Retouch: High-end smooth finish. Significantly reduce wrinkles and imperfections while keeping key biometric landmarks (moles, scars).";
    }
    retouchSteps.push(skinPrompt);
  }

  // Makeup: Lipstick (Reduced Opacity)
  if (beautySettings.lipstickIntensity > 0) {
    const opacity = Math.round(beautySettings.lipstickIntensity * 0.5); // Max 50% opacity
    retouchSteps.push(`Apply ${beautySettings.lipstickColor} lip tint (very natural, opacity ${opacity}%). Blend with natural lip lines.`);
  }

  // Makeup: Blush (Reduced Opacity)
  if (beautySettings.blushIntensity > 0) {
    const opacity = Math.round(beautySettings.blushIntensity * 0.3); // Max 30% opacity
    retouchSteps.push(`Apply extremely faint blush (opacity ${opacity}%) to cheeks.`);
  }

  // Makeup: Eyebrows
  if (beautySettings.eyebrowIntensity > 0) {
    const strength = Math.round(beautySettings.eyebrowIntensity * 0.5);
    retouchSteps.push(`Slightly define eyebrows (strength ${strength}%). Keep original shape and hair strokes.`);
  }

  // Makeup: Contour
  if (beautySettings.contourIntensity > 0) {
    const strength = Math.round(beautySettings.contourIntensity * 0.3);
    retouchSteps.push(`Apply imperceptible contour shading to define features (strength ${strength}%).`);
  }

  // --- 4. HAIR PROMPT (NEW) ---
  let hairInstruction = "";
  const hairSteps = [];

  // Hair Style Change
  if (beautySettings.hairStyle === 'short') {
      hairSteps.push("Change hairstyle to professional SHORT neat hair. Ensure hair does not cover eyebrows or ears.");
  } else if (beautySettings.hairStyle === 'long') {
      hairSteps.push("Change hairstyle to professional LONG neat hair, draped behind shoulders if possible. Ensure face visibility.");
  }

  // Hair Volume (Add Hair)
  if (beautySettings.hairVolume > 0) {
      // Map 0-100 to description
      const volDesc = beautySettings.hairVolume < 50 ? "slightly fuller" : "moderately thick and healthy";
      hairSteps.push(`Make hair look ${volDesc}. Fill in gaps or receding hairline naturally. Keep original hair color.`);
  }

  // Hair Color Change (NEW) - STRICT BIOMETRIC PROTECTION
  if (beautySettings.hairColor && beautySettings.hairColor !== 'Màu gốc' && beautySettings.hairColor !== 'original') {
      hairSteps.push(`Dye hair to ${beautySettings.hairColor}. 
      CRITICAL RULES FOR HAIR DYE:
      1. ONLY change the hair pixel color. 
      2. DO NOT change skin tone. Ensure clean segmentation between hair and forehead/neck. 
      3. Maintain natural hair shine, highlights, and individual strands. 
      4. Do NOT make it look like a wig. Realistic texture is mandatory.`);
  }

  if (hairSteps.length > 0) {
      hairInstruction = `TASK 4 (Hair): ${hairSteps.join(" ")}. STRICT: Do not alter face shape while changing hair.`;
  }

  if (retouchSteps.length > 0) {
    beautyInstruction = `TASK 3 (Retouch): ${retouchSteps.join(" ")}`;
  }

  // Combine Prompt
  let prompt = `Role: Expert ID Photo Editor (Biometric Passport Standards).
  Input: Image of a person.

  ${bgInstruction}
  ${clothingInstruction}
  ${beautyInstruction}
  ${hairInstruction}

  CRITICAL BIOMETRIC RULES (STRICT COMPLIANCE):
  1. **DO NOT ALTER FACIAL GEOMETRY**: The shape of eyes, nose, mouth, chin, ears, and head width MUST remain 100% identical to the original.
  2. **DO NOT REMOVE PERMANENT MARKS**: Moles (nốt ruồi), birthmarks, and scars must be preserved. Only remove temporary acne/redness if requested.
  3. **DO NOT CHANGE SKIN TONE**: Maintain the subject's natural ethnicity and skin color. Even when changing hair color, skin must remain untouched.
  4. **NATURALISM**: The result must look like a raw photograph, not a filtered selfie. Avoid 'wax figure' skin.
  5. **OUTPUT FORMAT**: Return a PNG image. If background removal is requested, the background MUST be transparent (Alpha Channel).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', 
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          // IMPORTANT: Return as PNG to support transparency
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error: any) {
    const errorStr = JSON.stringify(error);
    console.error("Gemini processing error:", errorStr);

    const isQuotaError = 
      error.status === 429 || 
      error.status === 'RESOURCE_EXHAUSTED' || 
      (error.error && error.error.code === 429) ||
      (error.error && error.error.status === 'RESOURCE_EXHAUSTED') ||
      (error.message && (error.message.includes('429') || error.message.includes('Quota'))) ||
      errorStr.includes('"code":429') || 
      errorStr.includes('"status":429') ||
      errorStr.includes('RESOURCE_EXHAUSTED') ||
      (error.name === 'ApiError' && error.status === 429);

    if (isQuotaError) {
      throw new Error("AI_QUOTA_EXCEEDED");
    }

    throw error;
  }
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing' | 'makeup';
type ViewMode = 'slider' | 'sideBySide';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  // processedUrl holds the result of the LAST SUCCESSFUL AI generation (Usually Transparent PNG)
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');
  const [viewMode, setViewMode] = useState<ViewMode>('slider');

  // Track the settings that generated the current `processedUrl`
  // NOTE: 'bg' is excluded from hash because we now handle background composition Client-Side!
  const [appliedHash, setAppliedHash] = useState<string>('');

  // Slider State
  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');

  // Generate a hash string for AI-related settings
  // We exclude 'background' from the AI hash because changing background 
  // no longer requires a new AI call (except for switching to ORIGINAL).
  const getAiSettingsHash = (s: PhotoSettings) => {
    const beauty = s.beauty;
    return JSON.stringify({
       // If background is ORIGINAL, it requires different AI processing (no removal)
       // If background is COLOR, it's all the same to AI (Transparent removal)
       isOriginalBg: s.background === BackgroundType.ORIGINAL, 
       cloth: s.clothingPrompt,
       blemish: beauty.removeBlemishes,
       smooth: beauty.smoothSkin,
       lipCol: beauty.lipstickColor,
       lipInt: beauty.lipstickIntensity,
       blush: beauty.blushIntensity,
       brow: beauty.eyebrowIntensity,
       contour: beauty.contourIntensity,
       hair: beauty.hairVolume,
       hairStyle: beauty.hairStyle,
       hairColor: beauty.hairColor 
    });
  };

  useEffect(() => {
    // On mount, set the initial hash based on default settings
    setAppliedHash(getAiSettingsHash(settings));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Check if there are pending AI changes
  const hasPendingAiChanges = useMemo(() => {
    const currentHash = getAiSettingsHash(settings);
    return currentHash !== appliedHash;
  }, [settings, appliedHash]);

  // --- AI HANDLER (BATCHED) ---
  const handleApplyAiChanges = async () => {
    const currentHash = getAiSettingsHash(settings);
    if (currentHash === appliedHash) return;

    setIsProcessing(true);
    setLoadingAction("AI đang tách nền & xử lý...");

    try {
      const isDefault = 
        settings.background === BackgroundType.ORIGINAL && 
        !settings.clothingPrompt && 
        !settings.beauty.removeBlemishes && 
        settings.beauty.smoothSkin === 0 &&
        settings.beauty.lipstickIntensity === 0 && 
        settings.beauty.blushIntensity === 0 &&
        settings.beauty.eyebrowIntensity === 0 &&
        settings.beauty.contourIntensity === 0 &&
        settings.beauty.hairVolume === 0 &&
        (settings.beauty.hairStyle === 'original' || !settings.beauty.hairStyle) &&
        (settings.beauty.hairColor === 'original' || !settings.beauty.hairColor || settings.beauty.hairColor === 'Màu gốc');

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        // Call AI Service. 
        // Important: this now returns a TRANSPARENT PNG (if not Original BG)
        const result = await processIDPhoto(
            originalImage, 
            settings.background, 
            settings.clothingPrompt, 
            settings.beauty, 
            settings.size
        );
        setProcessedUrl(result);
      }

      setAppliedHash(currentHash);

    } catch (err: any) {
      console.error(err);
      if (err.message === 'AI_QUOTA_EXCEEDED') {
          alert("HẾT LƯỢT AI (QUOTA EXCEEDED).\n\nVui lòng thử lại sau.");
      } else {
          alert("Lỗi xử lý AI. Vui lòng thử lại.");
      }
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  };

  // --- UI HANDLERS ---
  const handleBgChange = (bg: BackgroundType) => {
    // Changing BG is now instant (CSS only), unless switching To/From Original
    onUpdateSettings({ ...settings, background: bg });
  };

  const handleClothingClick = (prompt: string) => {
    onUpdateSettings({ ...settings, clothingPrompt: prompt });
  };

  const handleAiBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  const handleBlemishToggle = () => {
      const newBeauty = { ...settings.beauty, removeBlemishes: !settings.beauty.removeBlemishes };
      onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  const handleHairStyleChange = (style: 'original' | 'short' | 'long') => {
      const newBeauty = { ...settings.beauty, hairStyle: style };
      onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  // Client-side only (Lighting/Contrast/Tint) - Updates instantly via CSS
  const handleClientBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  // --- CSS HELPER: Get Background Color for Preview ---
  const getCurrentBgStyle = () => {
      if (settings.background === BackgroundType.ORIGINAL) return {};
      const bgConfig = config.backgroundConfig.find(b => b.type === settings.background);
      const color = bgConfig ? bgConfig.hexColor : '#ffffff';

      return {
          backgroundColor: color,
          backgroundImage: settings.background === BackgroundType.WHITE 
            ? 'none' 
            : `linear-gradient(to bottom, ${color}, ${color})` // Can add texture later
      };
  };

  // --- CSS FILTER GENERATOR ---
  const imageFilters = useMemo(() => {
    const { lighting, contrast, skinToneIntensity, skinToneType } = settings.beauty;
    const brightnessVal = 100 + (lighting * 1.5); 
    const contrastVal = 100 + (contrast * 1.5);

    let sepia = 0;
    let hue = 0;
    let saturate = 100;

    if (skinToneIntensity > 0) {
        if (skinToneType === SkinToneType.TAN) {
            sepia = skinToneIntensity * 0.3; 
            saturate = 100 - (skinToneIntensity * 0.1);
        } else if (skinToneType === SkinToneType.ROSY) {
            sepia = skinToneIntensity * 0.15;
            hue = -10; 
            saturate = 100 + (skinToneIntensity * 0.1);
        } else if (skinToneType === SkinToneType.FAIR) {
            saturate = 100 - (skinToneIntensity * 0.1);
        }
    }

    return `brightness(${brightnessVal}%) contrast(${contrastVal}%) saturate(${saturate}%) sepia(${sepia}%) hue-rotate(${hue}deg)`;
  }, [settings.beauty]);

  // --- FINAL EXPORT (COMPOSITING) ---
  // This step creates the final "Flat" image by drawing the background color
  // AND the transparent AI image onto a canvas.
  const handleFinish = () => {
    const finishExport = (imgSrc: string) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.src = imgSrc;
        img.crossOrigin = "anonymous";

        img.onload = () => {
            canvas.width = img.width;
            canvas.height = img.height;
            if (ctx) {
                // 1. Fill Background (Compositing)
                if (settings.background !== BackgroundType.ORIGINAL) {
                    const bgConfig = config.backgroundConfig.find(b => b.type === settings.background);
                    const color = bgConfig ? bgConfig.hexColor : '#ffffff';
                    ctx.fillStyle = color;
                    ctx.fillRect(0, 0, canvas.width, canvas.height);
                }

                // 2. Draw Subject (Transparent PNG or Original)
                ctx.filter = imageFilters;
                ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

                // 3. Export flattened image
                onProcessedImage(canvas.toDataURL('image/png', 1.0));
                onNext();
            }
        };
    };

    if (hasPendingAiChanges) {
        if (confirm("Bạn có thay đổi chưa áp dụng. Bạn có muốn áp dụng xử lý AI trước khi in không?")) {
            setIsProcessing(true);
            setLoadingAction("Đang xử lý lần cuối...");
            processIDPhoto(originalImage, settings.background, settings.clothingPrompt, settings.beauty, settings.size)
                .then((result) => {
                    setProcessedUrl(result);
                    setAppliedHash(getAiSettingsHash(settings));
                    finishExport(result);
                    setIsProcessing(false);
                })
                .catch((err) => {
                    setIsProcessing(false);
                    if (err.message === 'AI_QUOTA_EXCEEDED') {
                        alert("HẾT LƯỢT AI (QUOTA EXCEEDED).\nKhông thể áp dụng chỉnh sửa AI. Vui lòng thử lại sau.");
                    } else {
                        alert("Lỗi xử lý. Vui lòng thử lại.");
                    }
                });
        } else {
             finishExport(processedUrl);
        }
    } else {
        setIsProcessing(true);
        finishExport(processedUrl);
        setIsProcessing(false);
    }
  };

  const activeClothingOptions = config.clothingOptions.filter(item => item.gender === genderTab);
  const SkinToneOptions = [
    { id: SkinToneType.NATURAL, label: 'Tự nhiên', color: '#e5cba6' },
    { id: SkinToneType.FAIR, label: 'Trắng Sáng', color: '#fcebe3' },
    { id: SkinToneType.ROSY, label: 'Trắng Hồng', color: '#ffdee8' },
    { id: SkinToneType.TAN, label: 'Ngăm Khỏe', color: '#cd9b75' },
  ];

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-slate-100 overflow-hidden font-sans"
       onMouseUp={() => { isDraggingRef.current = false; }}
       onTouchEnd={() => { isDraggingRef.current = false; }}
    >
      {/* Sidebar */}
      <div className="w-full md:w-[420px] bg-white shadow-2xl z-20 flex flex-col h-full border-r border-gray-200">

        <div className="p-4 border-b border-gray-100 bg-white flex justify-between items-center">
          <h2 className="text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600 text-2xl">⚡</span> Chỉnh sửa
          </h2>
          <div className="flex flex-col items-end">
            <span className="text-[10px] font-bold text-green-600 bg-green-50 px-2 py-0.5 rounded-full border border-green-100">AI Separation</span>
          </div>
        </div>

        <div className="px-4 pt-4 pb-2">
          <div className="flex bg-gray-100 p-1 rounded-xl overflow-x-auto no-scrollbar">
            {[
              {id: 'background', label: '1. Nền'},
              {id: 'clothing', label: '2. Áo'},
              {id: 'makeup', label: '3. Makeup (AI)'},
              {id: 'beauty', label: '4. Bộ lọc Live'}
            ].map((tab) => (
               <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`flex-1 min-w-[70px] py-2.5 text-[11px] font-bold uppercase tracking-wide rounded-lg transition-all whitespace-nowrap ${
                  activeTab === tab.id 
                    ? 'bg-white text-brand-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-5 bg-white scrollbar-hide relative">

          {/* BACKGROUND TAB */}
          {activeTab === 'background' && (
            <div className="space-y-4 animate-fadeIn">
              <div className="grid grid-cols-2 gap-4">
                 {config.backgroundConfig.map(bg => (
                   <button 
                      key={bg.type}
                      onClick={() => handleBgChange(bg.type)} 
                      className={`relative h-28 rounded-2xl border-2 flex flex-col items-center justify-center gap-3 transition-all ${
                        settings.background === bg.type ? 'border-brand-500 bg-brand-50 ring-1 ring-brand-200' : 'border-slate-100 hover:bg-slate-50'
                      }`}
                    >
                      <div className="w-10 h-10 rounded-full shadow-inner border" style={{ backgroundColor: bg.hexColor }}></div>
                      <span className={`text-xs font-bold ${settings.background === bg.type ? 'text-brand-700' : 'text-gray-600'}`}>{bg.label}</span>
                    </button>
                ))}
                <button 
                  onClick={() => handleBgChange(BackgroundType.ORIGINAL)} 
                  className={`relative h-28 rounded-2xl border-2 flex flex-col items-center justify-center gap-3 transition-all ${
                    settings.background === BackgroundType.ORIGINAL ? 'border-brand-500 bg-brand-50 ring-1 ring-brand-200' : 'border-slate-100 hover:bg-slate-50'
                  }`}
                >
                  <div className="w-10 h-10 rounded-full bg-gray-300 flex items-center justify-center">📷</div>
                  <span className="text-xs font-bold text-gray-600">Ảnh Gốc</span>
                </button>
              </div>
              <div className="bg-blue-50 p-3 rounded-lg border border-blue-100 text-[11px] text-blue-700">
