                    <input type="range" min="0" max="100" step="20" value={settings.beauty.hairVolume} onChange={(e) => handleAiBeautyChange('hairVolume', Number(e.target.value))} className="w-full h-2 bg-orange-100 rounded-lg appearance-none cursor-pointer accent-orange-600" />
                  </div>

                  {/* Hair Color Palette */}
                  <div>
                    <div className="text-xs font-bold text-gray-600 mb-3 uppercase tracking-wider">Bảng màu tóc</div>
                    <div className="grid grid-cols-4 gap-3">
                         {(config.hairColorOptions || []).map((c) => {
                             const isSelected = settings.beauty.hairColor === c.label;
                             return (
                                <button 
                                    key={c.id}
                                    onClick={() => handleAiBeautyChange('hairColor', c.label)} 
                                    className={`
