                                    >
                                        {isSelected && c.hex !== 'transparent' && (
                                            <svg className="w-5 h-5 text-white drop-shadow-md" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
                                        )}
                                        {c.hex === 'transparent' && (
                                            <span className="text-[9px] font-bold text-gray-500">GỐC</span>
