                                    </div>
                                    <span className={`text-[10px] font-bold truncate max-w-full leading-tight text-center ${isSelected ? 'text-orange-700' : 'text-gray-500'}`}>
                                        {c.label}
                                    </span>
                                </button>
                             );
                         })}
                    </div>
                  </div>
              </div>

              <hr className="border-gray-100" />
              {/* Other controls (Blemish, Contour, Eyebrows, Lipstick, Blush) remain same... */}
              {/* Blemish Removal */}
              <div className="bg-white border border-gray-200 p-4 rounded-xl flex items-center justify-between">
                 <div className="flex items-center gap-3">
                   <div className="bg-blue-100 text-blue-600 p-2 rounded-lg"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z"></path></svg></div>
                   <div>
                     <h3 className="text-sm font-bold text-gray-800">Sạch mụn (Tự nhiên)</h3>
                     <p className="text-[10px] text-gray-400">Giữ nốt ruồi & sẹo (Sinh trắc học)</p>
                   </div>
                 </div>
                 <label className="relative inline-flex items-center cursor-pointer">
                    <input type="checkbox" className="sr-only peer" checked={settings.beauty.removeBlemishes} onChange={handleBlemishToggle} disabled={isProcessing} />
                    <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-brand-600"></div>
                 </label>
              </div>

              {/* Contour */}
              <div>
                  <div className="flex justify-between text-xs font-bold text-gray-600 mb-2">
                    <span className="flex items-center gap-1">
                        <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"></path></svg>
                        Tạo khối (Contour)
                    </span>
                    <span>{settings.beauty.contourIntensity}%</span>
                  </div>
                  <input type="range" min="0" max="100" step="20" value={settings.beauty.contourIntensity} onChange={(e) => handleAiBeautyChange('contourIntensity', Number(e.target.value))} className="w-full h-2 bg-stone-200 rounded-lg appearance-none cursor-pointer accent-stone-600" />
              </div>

              {/* Eyebrows */}
              <div>
                  <div className="flex justify-between text-xs font-bold text-gray-600 mb-2">
                    <span className="flex items-center gap-1">
                        <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg>
