              </div>
              <div className="grid grid-cols-2 gap-3 mb-4">
                <button onClick={() => handleClothingClick('')} className={`p-3 border-2 rounded-xl text-left transition-all ${!settings.clothingPrompt ? 'border-green-500 bg-green-50 shadow-md' : 'border-gray-100 hover:border-gray-300'}`}>
                   <div className="text-2xl mb-2">👕</div>
                   <div className="text-xs font-bold text-gray-800">Trang phục gốc</div>
                </button>
                {activeClothingOptions.map((item) => (
                  <button 
                    key={item.id} 
                    onClick={() => handleClothingClick(item.prompt)} 
                    className={`p-3 border-2 rounded-xl text-left transition-all group relative ${
                      settings.clothingPrompt === item.prompt 
                        ? `bg-white ${item.color} shadow-md` 
                        : 'bg-white border-gray-100 hover:border-gray-300'
                    }`}
                  >
                    <div className="text-2xl mb-2">{item.icon}</div>
                    <div className="text-xs font-bold text-gray-700">{item.label}</div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-gray-200 bg-white space-y-3 z-30">

           {/* APPLY AI BUTTON */}
           {hasPendingAiChanges && (
                <div className="animate-fadeIn pb-2 border-b border-gray-100 mb-2">
                    <button 
                        onClick={handleApplyAiChanges}
                        disabled={isProcessing}
                        className="w-full py-3 bg-gradient-to-r from-indigo-600 to-purple-600 text-white rounded-xl font-bold shadow-lg shadow-indigo-500/30 flex items-center justify-center gap-2 hover:shadow-xl transition-all active:scale-95"
                    >
                        <svg className="w-5 h-5 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z"></path></svg>
                        {isProcessing ? 'Đang xử lý...' : '✨ Áp dụng AI'}
                    </button>
                     <div className="text-center mt-1">
                        <span className="text-[10px] text-indigo-600 font-bold bg-indigo-50 px-2 py-0.5 rounded-full">Có thay đổi chưa áp dụng</span>
                    </div>
                </div>
            )}

           <button 
            onClick={handleFinish} 
            disabled={isProcessing} 
            className={`w-full py-4 rounded-xl font-bold shadow-lg flex items-center justify-center gap-2 transition-all transform active:scale-95 ${
              isProcessing 
                ? 'bg-gray-100 text-gray-400 cursor-wait' 
                : 'bg-brand-600 hover:bg-brand-700 text-white hover:shadow-xl'
            }`}
          >
            {isProcessing ? 'Đang xử lý...' : 'Hoàn tất & In Ảnh'}
          </button>

          <button 
            onClick={onRetake} 
            disabled={isProcessing}
            className="w-full py-3 bg-white border border-slate-200 text-slate-600 rounded-xl font-bold hover:bg-slate-50 hover:text-red-500 transition"
          >
            Chụp lại
          </button>
        </div>
      </div>

      {/* Preview Area */}
      <div className="flex-1 bg-slate-100 relative flex flex-col items-center justify-center p-6"
           onMouseMove={(e) => {
             if (isDraggingRef.current && imageContainerRef.current) {
                const rect = imageContainerRef.current.getBoundingClientRect();
                const clientX = 'touches' in e ? (e as any).touches[0].clientX : (e as any).clientX;
                const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
                setSliderPosition((x / rect.width) * 100);
             }
           }}
           onTouchMove={(e) => {
             if (isDraggingRef.current && imageContainerRef.current) {
                const rect = imageContainerRef.current.getBoundingClientRect();
                const clientX = e.touches[0].clientX;
                const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
                setSliderPosition((x / rect.width) * 100);
             }
           }}
      >
        <div className="absolute top-4 z-10 bg-white/90 backdrop-blur text-slate-600 p-1.5 rounded-full text-xs font-bold border border-white shadow-sm flex items-center gap-1 select-none animate-fadeIn">
          <button 
             onClick={() => setViewMode('slider')}
             className={`px-3 py-1.5 rounded-full transition-all flex items-center gap-1 ${viewMode === 'slider' ? 'bg-brand-600 text-white shadow-md' : 'hover:bg-gray-200'}`}
          >
             <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4"></path></svg>
             Trượt
          </button>
          <button 
             onClick={() => setViewMode('sideBySide')}
             className={`px-3 py-1.5 rounded-full transition-all flex items-center gap-1 ${viewMode === 'sideBySide' ? 'bg-brand-600 text-white shadow-md' : 'hover:bg-gray-200'}`}
          >
             <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 10h16M4 14h16M4 18h16"></path></svg>
             Song Song
          </button>
        </div>

        {/* LOADING OVERLAY */}
        {isProcessing && (
            <div className="absolute inset-0 z-30 bg-black/40 flex flex-col items-center justify-center backdrop-blur-[2px]">
               <div className="bg-white p-6 rounded-2xl shadow-2xl flex flex-col items-center animate-bounce-in">
                 <div className="w-12 h-12 border-4 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-3"></div>
                 <p className="text-brand-800 font-bold text-sm">{loadingAction}</p>
                 <p className="text-[10px] text-gray-400 mt-1">Gemini AI Processor ⚡</p>
               </div>
            </div>
          )}

        {viewMode === 'slider' ? (
            // --- SLIDER VIEW MODE ---
            <div 
              ref={imageContainerRef}
              className="relative shadow-2xl select-none cursor-ew-resize overflow-hidden rounded-sm border-4 border-brand-200 bg-white" 
              style={{ 
                 maxHeight: '85vh', 
                 aspectRatio: settings.size === PhotoSize.SIZE_5X5 ? '1/1' : '2/3',
                 height: '85vh'
              }}
              onMouseDown={() => { isDraggingRef.current = true; }}
              onTouchStart={() => { isDraggingRef.current = true; }}
            >
              {/* LAYER 1: BOTTOM (ORIGINAL / BEFORE) */}
              <img 
                src={originalImage} 
                alt="Before" 
                className="absolute inset-0 w-full h-full object-contain pointer-events-none" 
              />

              {/* LAYER 2: TOP (PROCESSED / AFTER) */}
              <div 
                  className="absolute inset-0 w-full h-full pointer-events-none"
                  style={{ 
                    clipPath: `inset(0 ${100 - sliderPosition}% 0 0)`, // Reveals from left
                  }}
              >
                 <img 
                    src={processedUrl} 
                    alt="After" 
                    className="absolute inset-0 w-full h-full object-contain"
                    style={{ filter: imageFilters }}
                 />
              </div>

              {/* Slider Handle Line */}
              <div 
                className="absolute top-0 bottom-0 w-1 bg-white cursor-ew-resize z-20 shadow-[0_0_10px_rgba(0,0,0,0.3)]"
                style={{ left: `${sliderPosition}%` }}
              >
                <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-8 h-8 bg-white rounded-full shadow-xl flex items-center justify-center border border-gray-200">
                  <svg className="w-4 h-4 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 9l4-4 4 4m0 6l-4 4-4-4"></path></svg>
                </div>
              </div>

               {/* Labels */}
               <div className="absolute bottom-4 left-4 bg-black/50 text-white text-[10px] font-bold px-2 py-1 rounded backdrop-blur-sm pointer-events-none">TRƯỚC</div>
               <div className="absolute bottom-4 right-4 bg-brand-600/80 text-white text-[10px] font-bold px-2 py-1 rounded backdrop-blur-sm pointer-events-none">SAU</div>
            </div>
        ) : (
            // --- SIDE BY SIDE VIEW MODE ---
            <div className="flex gap-4 items-center justify-center h-[85vh] w-full px-4">
                 {/* Original */}
                 <div className="relative h-full flex-1 bg-white shadow-xl border-2 border-slate-200 rounded-lg overflow-hidden group">
                     <img src={originalImage} className="w-full h-full object-contain" alt="Original" />
                     <div className="absolute bottom-3 left-1/2 transform -translate-x-1/2 bg-black/60 text-white text-xs font-bold px-3 py-1 rounded-full backdrop-blur">Ảnh Gốc</div>
                 </div>

                 {/* Processed */}
                 <div 
                    className="relative h-full flex-1 shadow-xl border-2 border-brand-500 rounded-lg overflow-hidden group"
                 >
                     <img src={processedUrl} className="absolute inset-0 w-full h-full object-contain" style={{ filter: imageFilters }} alt="Processed" />

                     <div className="absolute bottom-3 left-1/2 transform -translate-x-1/2 bg-brand-600/90 text-white text-xs font-bold px-3 py-1 rounded-full backdrop-blur">Kết quả</div>
                 </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default ImageEditor;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing' | 'makeup';
type ViewMode = 'slider' | 'sideBySide';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  // processedUrl holds the result of the LAST SUCCESSFUL AI generation (Now Opaque)
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');
  const [viewMode, setViewMode] = useState<ViewMode>('slider');

  // Slider State
  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');

  // --- AI HASH LOGIC ---
  // Generate a hash string for AI-related settings
  const getAiSettingsHash = useCallback((s: PhotoSettings) => {
    const beauty = s.beauty;
    return JSON.stringify({
       background: s.background, // INCLUDED: Background change requires AI
       cloth: s.clothingPrompt,
       blemish: beauty.removeBlemishes,
       smooth: beauty.smoothSkin,
       lipCol: beauty.lipstickColor,
       lipInt: beauty.lipstickIntensity,
       blush: beauty.blushIntensity,
       brow: beauty.eyebrowIntensity,
       contour: beauty.contourIntensity,
       hair: beauty.hairVolume,
       hairStyle: beauty.hairStyle,
       hairColor: beauty.hairColor 
    });
  }, []);

  // Calculate the Hash that represents the "Raw/Original" image state
  // (Original BG, No Beauty, No Clothing change)
  const getRawStateHash = useCallback(() => {
     return JSON.stringify({
       background: BackgroundType.ORIGINAL,
       cloth: undefined,
       blemish: false,
       smooth: 0,
       lipCol: settings.beauty.lipstickColor, // Color choice is irrelevant if intensity is 0, but keep consistent
       lipInt: 0,
       blush: 0,
       brow: 0,
       contour: 0,
       hair: 0,
       hairStyle: 'original',
       hairColor: 'original'
     });
     // Note: We use values that result in "No AI Change"
  }, [settings.beauty.lipstickColor]);

  // appliedHash tracks which settings are currently BAKED into processedUrl.
  // We initialize it to the RAW hash because processedUrl starts as originalImage.
  const [appliedHash, setAppliedHash] = useState<string>(getRawStateHash());

  // Check if there are pending AI changes
  const hasPendingAiChanges = useMemo(() => {
    const currentHash = getAiSettingsHash(settings);

    // Special handling: If appliedHash is empty (first load), treat as Raw
    const safeAppliedHash = appliedHash || getRawStateHash();

    return currentHash !== safeAppliedHash;
  }, [settings, appliedHash, getAiSettingsHash, getRawStateHash]);


  // --- AI HANDLER (BATCHED) ---
  const handleApplyAiChanges = useCallback(async () => {
    const currentHash = getAiSettingsHash(settings);

    setIsProcessing(true);
    setLoadingAction("AI đang xử lý (Thay nền & Làm đẹp)...");

    try {
      const isDefault = 
        settings.background === BackgroundType.ORIGINAL && 
        !settings.clothingPrompt && 
        !settings.beauty.removeBlemishes && 
        settings.beauty.smoothSkin === 0 &&
        settings.beauty.lipstickIntensity === 0 && 
        settings.beauty.blushIntensity === 0 &&
        settings.beauty.eyebrowIntensity === 0 &&
        settings.beauty.contourIntensity === 0 &&
        settings.beauty.hairVolume === 0 &&
        (settings.beauty.hairStyle === 'original' || !settings.beauty.hairStyle) &&
        (settings.beauty.hairColor === 'original' || !settings.beauty.hairColor || settings.beauty.hairColor === 'Màu gốc');

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        // Call AI Service. Returns OPAQUE image with baked background
        const result = await processIDPhoto(
            originalImage, 
            settings.background, 
            settings.clothingPrompt, 
            settings.beauty, 
            settings.size
        );
        setProcessedUrl(result);
      }

      setAppliedHash(currentHash);

    } catch (err: any) {
      console.error(err);
      if (err.message === 'AI_QUOTA_EXCEEDED') {
          alert("HẾT LƯỢT AI (QUOTA EXCEEDED).\n\nVui lòng thử lại sau.");
      } else {
          alert("Lỗi xử lý AI. Vui lòng thử lại.");
      }
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  }, [settings, originalImage, getAiSettingsHash]);

  // REMOVED: useEffect for auto-triggering AI on mount. 
  // We now rely purely on user interaction to click "Apply AI".


  // --- UI HANDLERS ---
  const handleBgChange = (bg: BackgroundType) => {
    // Changing BG now triggers pending state for AI
    onUpdateSettings({ ...settings, background: bg });
  };

  const handleClothingClick = (prompt: string) => {
    onUpdateSettings({ ...settings, clothingPrompt: prompt });
  };

  const handleAiBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  const handleBlemishToggle = () => {
      const newBeauty = { ...settings.beauty, removeBlemishes: !settings.beauty.removeBlemishes };
      onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  const handleHairStyleChange = (style: 'original' | 'short' | 'long') => {
      const newBeauty = { ...settings.beauty, hairStyle: style };
      onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  // Client-side only (Lighting/Contrast/Tint) - Updates instantly via CSS
  const handleClientBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  // --- CSS FILTER GENERATOR ---
  const imageFilters = useMemo(() => {
    const { lighting, contrast, skinToneIntensity, skinToneType } = settings.beauty;
    const brightnessVal = 100 + (lighting * 1.5); 
    const contrastVal = 100 + (contrast * 1.5);

    let sepia = 0;
    let hue = 0;
    let saturate = 100;

    if (skinToneIntensity > 0) {
        if (skinToneType === SkinToneType.TAN) {
            sepia = skinToneIntensity * 0.3; 
            saturate = 100 - (skinToneIntensity * 0.1);
        } else if (skinToneType === SkinToneType.ROSY) {
            sepia = skinToneIntensity * 0.15;
            hue = -10; 
            saturate = 100 + (skinToneIntensity * 0.1);
        } else if (skinToneType === SkinToneType.FAIR) {
            saturate = 100 - (skinToneIntensity * 0.1);
        }
    }

    return `brightness(${brightnessVal}%) contrast(${contrastVal}%) saturate(${saturate}%) sepia(${sepia}%) hue-rotate(${hue}deg)`;
  }, [settings.beauty]);

  // --- FINAL EXPORT ---
  const handleFinish = () => {
    const finishExport = (imgSrc: string) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.src = imgSrc;
        img.crossOrigin = "anonymous";

        img.onload = () => {
            canvas.width = img.width;
            canvas.height = img.height;
            if (ctx) {
                // Draw Subject (Opaque Image from AI)
                ctx.filter = imageFilters;
                ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

                // Export flattened image
                onProcessedImage(canvas.toDataURL('image/png', 1.0));
                onNext();
            }
        };
    };

    if (hasPendingAiChanges) {
        if (confirm("Bạn có thay đổi chưa áp dụng (Nền/Áo/Makeup). Bạn có muốn áp dụng xử lý AI trước khi in không?")) {
            // Apply then finish
            const currentHash = getAiSettingsHash(settings);
            setIsProcessing(true);
            setLoadingAction("Đang xử lý lần cuối...");

            processIDPhoto(originalImage, settings.background, settings.clothingPrompt, settings.beauty, settings.size)
                .then((result) => {
                    setProcessedUrl(result);
                    setAppliedHash(currentHash);
                    finishExport(result);
                    setIsProcessing(false);
                })
                .catch((err) => {
                    setIsProcessing(false);
                    if (err.message === 'AI_QUOTA_EXCEEDED') {
                        alert("HẾT LƯỢT AI (QUOTA EXCEEDED).\nKhông thể áp dụng chỉnh sửa AI. Vui lòng thử lại sau.");
                    } else {
                        alert("Lỗi xử lý. Vui lòng thử lại.");
                    }
                });
        } else {
             finishExport(processedUrl);
        }
    } else {
        setIsProcessing(true);
        finishExport(processedUrl);
        setIsProcessing(false);
    }
  };

  const activeClothingOptions = config.clothingOptions.filter(item => item.gender === genderTab);
  const SkinToneOptions = [
    { id: SkinToneType.NATURAL, label: 'Tự nhiên', color: '#e5cba6' },
    { id: SkinToneType.FAIR, label: 'Trắng Sáng', color: '#fcebe3' },
    { id: SkinToneType.ROSY, label: 'Trắng Hồng', color: '#ffdee8' },
    { id: SkinToneType.TAN, label: 'Ngăm Khỏe', color: '#cd9b75' },
  ];

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-slate-100 overflow-hidden font-sans"
       onMouseUp={() => { isDraggingRef.current = false; }}
       onTouchEnd={() => { isDraggingRef.current = false; }}
    >
      {/* Sidebar */}
      <div className="w-full md:w-[420px] bg-white shadow-2xl z-20 flex flex-col h-full border-r border-gray-200">

        <div className="p-4 border-b border-gray-100 bg-white flex justify-between items-center">
          <h2 className="text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600 text-2xl">⚡</span> Chỉnh sửa
          </h2>
          <div className="flex flex-col items-end">
            <span className="text-[10px] font-bold text-purple-600 bg-purple-50 px-2 py-0.5 rounded-full border border-purple-100">AI Generative Fill</span>
          </div>
        </div>

        <div className="px-4 pt-4 pb-2">
          <div className="flex bg-gray-100 p-1 rounded-xl overflow-x-auto no-scrollbar">
            {[
              {id: 'background', label: '1. Nền'},
              {id: 'clothing', label: '2. Áo'},
              {id: 'makeup', label: '3. Makeup (AI)'},
              {id: 'beauty', label: '4. Bộ lọc Live'}
            ].map((tab) => (
               <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`flex-1 min-w-[70px] py-2.5 text-[11px] font-bold uppercase tracking-wide rounded-lg transition-all whitespace-nowrap ${
                  activeTab === tab.id 
                    ? 'bg-white text-brand-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-5 bg-white scrollbar-hide relative">

          {/* BACKGROUND TAB */}
          {activeTab === 'background' && (
            <div className="space-y-4 animate-fadeIn">
              <div className="grid grid-cols-2 gap-4">
                 {config.backgroundConfig.map(bg => (
                   <button 
                      key={bg.type}
                      onClick={() => handleBgChange(bg.type)} 
                      className={`relative h-28 rounded-2xl border-2 flex flex-col items-center justify-center gap-3 transition-all ${
                        settings.background === bg.type ? 'border-brand-500 bg-brand-50 ring-1 ring-brand-200' : 'border-slate-100 hover:bg-slate-50'
                      }`}
                    >
                      <div className="w-10 h-10 rounded-full shadow-inner border" style={{ backgroundColor: bg.hexColor }}></div>
                      <span className={`text-xs font-bold ${settings.background === bg.type ? 'text-brand-700' : 'text-gray-600'}`}>{bg.label}</span>
                    </button>
                ))}
                <button 
                  onClick={() => handleBgChange(BackgroundType.ORIGINAL)} 
                  className={`relative h-28 rounded-2xl border-2 flex flex-col items-center justify-center gap-3 transition-all ${
                    settings.background === BackgroundType.ORIGINAL ? 'border-brand-500 bg-brand-50 ring-1 ring-brand-200' : 'border-slate-100 hover:bg-slate-50'
                  }`}
                >
                  <div className="w-10 h-10 rounded-full bg-gray-300 flex items-center justify-center">📷</div>
                  <span className="text-xs font-bold text-gray-600">Ảnh Gốc</span>
                </button>
              </div>
              <div className="bg-yellow-50 p-3 rounded-lg border border-yellow-100 text-[11px] text-yellow-800">
                  ⚡ <b>Lưu ý:</b> Bấm <b>"Áp dụng AI"</b> bên dưới để hệ thống bắt đầu xử lý tách nền và làm đẹp.
              </div>
            </div>
          )}

          {/* BEAUTY TAB (Lighting, Tone - LIVE FILTERS ONLY) */}
          {activeTab === 'beauty' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="bg-green-50 p-3 rounded-xl border border-green-100 flex gap-2 items-center">
                 <span className="text-lg">⚡</span>
                 <div>
                    <p className="text-[11px] text-green-700 font-medium">Bộ lọc trực tiếp (Không tốn AI)</p>
                 </div>
              </div>

              {/* Lighting */}
              <div>
                <h3 className="text-sm font-bold text-gray-800 mb-3 flex items-center gap-2"><svg className="w-4 h-4 text-yellow-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z"></path></svg> Ánh sáng</h3>
                <div className="space-y-4 px-2">
