                    className="relative h-full flex-1 shadow-xl border-2 border-brand-500 rounded-lg overflow-hidden group"
                 >
                     <img src={processedUrl} className="absolute inset-0 w-full h-full object-contain" style={{ filter: imageFilters }} alt="Processed" />

                     <div className="absolute bottom-3 left-1/2 transform -translate-x-1/2 bg-brand-600/90 text-white text-xs font-bold px-3 py-1 rounded-full backdrop-blur">Kết quả</div>
                 </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default ImageEditor;

import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize, SkinToneType } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `Check ID Photo compliance. Output JSON. 
            Requirements: Face front-facing, eyes open, mouth closed, sufficient lighting.
            'instruction': Vietnamese command (e.g. "Mở mắt to", "Nhìn thẳng").
            If perfect: "Giữ nguyên".` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    const errorStr = JSON.stringify(error, null, 2);
    console.error("AI Analysis Error", errorStr);

    const isQuotaError = 
      error.status === 429 || 
      error.status === 'RESOURCE_EXHAUSTED' || 
      (error.error && error.error.code === 429) ||
      (error.error && error.error.status === 'RESOURCE_EXHAUSTED') ||
      (error.message && (error.message.includes('429') || error.message.includes('Quota') || error.message.includes('Limit'))) ||
      errorStr.includes('"code":429') || 
      errorStr.includes('"status":429') ||
      errorStr.includes('RESOURCE_EXHAUSTED') ||
      (error.name === 'ApiError' && error.status === 429);

    if (isQuotaError) {
       return { 
        isCompliant: true, 
        status: 'VALID', 
        feedback: 'AI_LIMIT', 
        instruction: 'Hết lượt AI. Chuyển thủ công.', 
        faceDetected: true 
      };
    }

    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Offline Mode', 
      instruction: 'Chụp thủ công', 
      faceDetected: true 
    };
  }
};

/**
 * Processes the ID photo using AI in a SINGLE BATCH.
 * STRICT BIOMETRIC PRESERVATION.
 * UPDATED: Generates OPAQUE background directly (No Alpha Channel).
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings, 
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // --- 1. BACKGROUND PROMPT (BAKED COLORS) ---
  let bgInstruction = "";

  if (bgType === BackgroundType.ORIGINAL) {
    bgInstruction = "TASK 1 (Background): Keep the original background exactly as is.";
  } else if (bgType === BackgroundType.WHITE) {
    bgInstruction = "TASK 1 (Background): Replace background with SOLID PURE WHITE (Hex #FFFFFF). Ensure hair strands blend naturally with the white background.";
  } else if (bgType === BackgroundType.BLUE) {
    bgInstruction = "TASK 1 (Background): Replace background with SOLID ID PHOTO BLUE (Hex #2792ff). Ensure NO white halos around hair. Blend hair strands into the blue background naturally.";
  } else if (bgType === BackgroundType.GRAY) {
    bgInstruction = "TASK 1 (Background): Replace background with SOLID NEUTRAL GRAY (Hex #d1d5db).";
  }

  // --- 2. CLOTHING PROMPT ---
  let clothingInstruction = "TASK 2 (Clothing): Keep original clothing.";
  if (clothingPrompt) {
    clothingInstruction = `TASK 2 (Clothing): Replace outfit with: "${clothingPrompt}". 
    - Ensure the collar fits the neck perfectly. 
    - Adjust lighting on clothes to match the face.
    - Style: Professional ID Photo.`;
  }

  // --- 3. BEAUTY / RETOUCH PROMPT ---
  let beautyInstruction = "TASK 3 (Retouch): No makeup changes.";
  const retouchSteps = [];

  // Blemishes
  if (beautySettings.removeBlemishes) {
    retouchSteps.push("Subtly reduce temporary acne visibility (redness). STRICTLY KEEP MOLES (nốt ruồi) AND SCARS (sẹo).");
  }

  // Smooth Skin
  if (beautySettings.smoothSkin > 0) {
    const val = beautySettings.smoothSkin;
    let skinPrompt = "";
    if (val <= 30) {
        skinPrompt = "Level 1 Skin Retouch: Remove oiliness/shine only. Keep 100% natural skin texture.";
    } else if (val <= 70) {
        skinPrompt = "Level 2 Skin Retouch: Soften pore visibility slightly. Maintain natural skin grain.";
    } else {
        skinPrompt = "Level 3 Skin Retouch: Soft finish. But MUST retain biometric features.";
    }
    retouchSteps.push(skinPrompt);
  }

  // Makeup Steps
  if (beautySettings.lipstickIntensity > 0) {
    const opacity = Math.round(beautySettings.lipstickIntensity * 0.5); 
    retouchSteps.push(`Apply ${beautySettings.lipstickColor} lip tint (very natural, opacity ${opacity}%).`);
  }
  if (beautySettings.blushIntensity > 0) {
    const opacity = Math.round(beautySettings.blushIntensity * 0.3);
    retouchSteps.push(`Apply extremely faint blush (opacity ${opacity}%) to cheeks.`);
  }
  if (beautySettings.eyebrowIntensity > 0) {
    const strength = Math.round(beautySettings.eyebrowIntensity * 0.5);
    retouchSteps.push(`Slightly define eyebrows (strength ${strength}%). Keep original shape.`);
  }
  if (beautySettings.contourIntensity > 0) {
    const strength = Math.round(beautySettings.contourIntensity * 0.3);
    retouchSteps.push(`Apply imperceptible contour shading (strength ${strength}%).`);
  }

  // --- 4. HAIR PROMPT ---
  let hairInstruction = "";
  const hairSteps = [];

  if (beautySettings.hairStyle === 'short') {
      hairSteps.push("Change hairstyle to professional SHORT neat hair. Ensure hair does not cover eyebrows.");
  } else if (beautySettings.hairStyle === 'long') {
      hairSteps.push("Change hairstyle to professional LONG neat hair. Ensure face visibility.");
  }

  if (beautySettings.hairVolume > 0) {
      const volDesc = beautySettings.hairVolume < 50 ? "slightly fuller" : "moderately thick";
      hairSteps.push(`Make hair look ${volDesc}. Fill in gaps naturally.`);
  }

  if (beautySettings.hairColor && beautySettings.hairColor !== 'Màu gốc' && beautySettings.hairColor !== 'original') {
      hairSteps.push(`Dye hair to ${beautySettings.hairColor}. 
      CRITICAL: ONLY change hair color. Do NOT change skin tone. Maintain natural hair shine.`);
  }

  if (hairSteps.length > 0) {
      hairInstruction = `TASK 4 (Hair): ${hairSteps.join(" ")}. STRICT: Do not alter face shape.`;
  }

  if (retouchSteps.length > 0) {
    beautyInstruction = `TASK 3 (Retouch): ${retouchSteps.join(" ")}`;
  }

  // Combine Prompt with STRICT BIOMETRIC RULES
  let prompt = `Role: Expert Forensic ID Photo Editor (Biometric Passport Standards).
  Input: Image of a person.

  ${bgInstruction}
  ${clothingInstruction}
  ${beautyInstruction}
  ${hairInstruction}

  CRITICAL BIOMETRIC PRESERVATION RULES (ZERO TOLERANCE):
  1. **DO NOT ALTER FACIAL GEOMETRY**: The structure of the face (jawline, chin width, eye distance, nose shape, cheekbones) MUST remain 100% identical to the source. DO NOT "slimming" the face.
  2. **DO NOT REMOVE PERMANENT MARKS**: Moles (nốt ruồi), birthmarks, and scars are BIOMETRIC IDENTIFIERS. They MUST be preserved. Only temporary acne/redness may be reduced.
  3. **DO NOT CHANGE SKIN TONE**: Maintain the subject's natural ethnicity and skin color EXACTLY.
  4. **DO NOT ENLARGE EYES**: Keep eyes natural size and shape.
  5. **NATURALISM**: The result must look like a raw photograph taken in a studio, NOT a filter or digital painting.
  6. **OUTPUT FORMAT**: Return a high-quality JPEG image. NO TRANSPARENCY. The background color must be baked into the image pixels.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', 
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          // IMPORTANT: Return as JPEG/PNG (Opaque)
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error: any) {
    const errorStr = JSON.stringify(error);
    console.error("Gemini processing error:", errorStr);

    const isQuotaError = 
      error.status === 429 || 
      error.status === 'RESOURCE_EXHAUSTED' || 
      (error.error && error.error.code === 429) ||
      (error.error && error.error.status === 'RESOURCE_EXHAUSTED') ||
      (error.message && (error.message.includes('429') || error.message.includes('Quota'))) ||
      errorStr.includes('"code":429') || 
      errorStr.includes('"status":429') ||
      errorStr.includes('RESOURCE_EXHAUSTED') ||
      (error.name === 'ApiError' && error.status === 429);

    if (isQuotaError) {
      throw new Error("AI_QUOTA_EXCEEDED");
    }

    throw error;
  }
};

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { PhotoSize } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';

// Polyfill definitions for ImageCapture API (experimental)
interface PhotoCapabilities {
  redEyeReduction: 'never' | 'always' | 'controllable';
  imageHeight: { min: number; max: number; step: number };
  imageWidth: { min: number; max: number; step: number };
  fillLightMode: string[];
}

interface PhotoSettings {
  fillLightMode?: string;
  imageHeight?: number;
  imageWidth?: number;
  redEyeReduction?: boolean;
}

declare class ImageCapture {
  constructor(track: MediaStreamTrack);
  takePhoto(photoSettings?: PhotoSettings): Promise<Blob>;
  getPhotoCapabilities(): Promise<PhotoCapabilities>;
  grabFrame(): Promise<ImageBitmap>;
}

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

// Strict State Machine for Biometric Validation
type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

// Short mechanical shutter sound (Base64 MP3)
const SHUTTER_SOUND = "data:audio/mp3;base64,";

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null); // Separate canvas for low-res analysis
  const shutterAudioRef = useRef<HTMLAudioElement | null>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);
  const [isCapturing, setIsCapturing] = useState(false); // New state for capture loading

  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  // AI Validation State
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('Đang xử lý');
  const [instruction, setInstruction] = useState<string>('');

  // NEW: Kill switch for AI when quota is exceeded
  const [aiLimitReached, setAiLimitReached] = useState(false);

  // --- AUTO CAPTURE STATE ---
  const [isAutoCaptureEnabled, setIsAutoCaptureEnabled] = useState(false);
  const hasAutoCapturedForCurrentValidRef = useRef(false);

  // Ref to track if an analysis request is currently in flight
  const isAnalyzingRef = useRef(false);
  // Using ReturnType<typeof setInterval> to handle both NodeJS and Browser environments
  const analysisIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Audio Feedback Ref to prevent repetition
  const lastSpokenRef = useRef<string>('');

  useEffect(() => {
    getDevices();
    startCamera();

    // Initialize Shutter Sound
    const audio = new Audio(SHUTTER_SOUND);
    shutterAudioRef.current = audio;

    return () => {
      stopCamera();
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
      window.speechSynthesis.cancel(); // Stop speaking on unmount
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (selectedDeviceId) startCamera(selectedDeviceId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDeviceId]);

  // Start AI Analysis Loop when stream is active
  useEffect(() => {
    // If AI limit reached (429), strictly do NOT start interval
    if (stream && !countdown && !isCapturing && !aiLimitReached) {
      // Run analysis every 5 seconds
      analysisIntervalRef.current = setInterval(performAIAnalysis, 5000);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    };
  }, [stream, countdown, selectedSize, isCapturing, aiLimitReached]); 

  // --- AUTO CAPTURE LOGIC ---
  useEffect(() => {
    if (validationStatus === 'valid') {
       if (isAutoCaptureEnabled && !hasAutoCapturedForCurrentValidRef.current && countdown === null && !isCapturing) {
          hasAutoCapturedForCurrentValidRef.current = true;
          setCountdown(3);
       }
    } else {
       // Reset trigger when status moves away from valid
       hasAutoCapturedForCurrentValidRef.current = false;
    }
  }, [validationStatus, isAutoCaptureEnabled, countdown, isCapturing]);

  // --- TEXT TO SPEECH HELPER ---
  const speak = (text: string, force: boolean = false) => {
      // Don't speak if already speaking the same thing or if disabled
      if (!text) return;
      if (!force && lastSpokenRef.current === text) return;

      // Cancel previous if new text is urgent (force=true) or different
      if (force || window.speechSynthesis.speaking) {
          window.speechSynthesis.cancel();
      }

      const utterance = new SpeechSynthesisUtterance(text);
      utterance.lang = 'vi-VN'; // Vietnamese
      utterance.rate = 1.1; // Slightly faster
      utterance.pitch = 1.0;

      // Fallback if Vietnamese voice not found, but modern browsers support it
      const voices = window.speechSynthesis.getVoices();
      const vnVoice = voices.find(v => v.lang.includes('vi'));
      if (vnVoice) utterance.voice = vnVoice;

      window.speechSynthesis.speak(utterance);
      lastSpokenRef.current = text;
  };

  // Trigger Audio Feedback on Instruction Change
  useEffect(() => {
     if (countdown !== null) return; // Don't speak instructions during countdown

     if (aiLimitReached) {
         if (lastSpokenRef.current !== 'AI_STOP') {
             speak("Hết lượt AI, vui lòng chụp thủ công", true);
             lastSpokenRef.current = 'AI_STOP';
         }
         return;
     }

     if (instruction) {
         // Only speak meaningful instructions
         if (validationStatus === 'valid') {
             // Speak only once when becoming valid
             if (lastSpokenRef.current !== 'ok') {
                 speak("Tuyệt vời, giữ nguyên tư thế", true);
                 lastSpokenRef.current = 'ok';
             }
         } else if (validationStatus === 'adjusting' || validationStatus === 'searching') {
             // Avoid repeating "Move to frame" too much
             speak(instruction); 
         }
     }
  }, [instruction, validationStatus, countdown, aiLimitReached]);

  // Helper to calculate exact crop coordinates based on current video and selected size
  const getCropDimensions = (sourceW: number, sourceH: number) => {
    let targetRatio = 2/3; // Default 4x6
    if (selectedSize === PhotoSize.SIZE_5X5) targetRatio = 1;
    if (selectedSize === PhotoSize.SIZE_3X4) targetRatio = 3/4;

    const sourceRatio = sourceW / sourceH;
    let cropW, cropH, startX, startY;

    if (sourceRatio > targetRatio) {
      // Source is wider than target: Crop Width (vertical bars)
      // Usually desktop webcam (16:9). We use full height.
      cropH = sourceH;
      cropW = cropH * targetRatio;
      startX = (sourceW - cropW) / 2;
      startY = 0;
    } else {
      // Source is taller than target: Crop Height (horizontal bars)
      // Usually mobile phone (9:16). We have vertical space to slide.
      cropW = sourceW;
      cropH = cropW / targetRatio;
      startX = 0;

      // SHIFT LOGIC:
      // Instead of centering ((sourceH - cropH) / 2), we shift the crop window DOWN relative to the source video.
      // This forces the captured area to be lower on the sensor, capturing more body/shoulders.
      // 0.5 = Center. 0.7 = 70% down.
      const verticalBias = 0.65; 
      startY = (sourceH - cropH) * verticalBias;
    }

    return {
      x: Math.floor(startX),
      y: Math.floor(startY),
      w: Math.floor(cropW),
      h: Math.floor(cropH)
    };
  };

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current || aiLimitReached) return;

    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');

      if (video.readyState === 4 && ctx) {
        // Calculate the exact crop that the user sees and will capture
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);

        // Resize for analysis (height 320px is sufficient for face detection)
        // Maintain aspect ratio of the CROP, not the full video
        const analysisH = 320;
        const analysisW = Math.floor(analysisH * (crop.w / crop.h));

        canvas.width = analysisW;
        canvas.height = analysisH;

        // Draw MIRRORED crop to match user experience
        ctx.save();
        ctx.translate(canvas.width, 0);
        ctx.scale(-1, 1);
        ctx.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        ctx.restore();

        const base64 = canvas.toDataURL('image/jpeg', 0.6); // Low quality is enough for structure check

        // Show "Scanning" state briefly if we were previously idle
        if (validationStatus === 'searching') setValidationStatus('analyzing');

        const result = await analyzeIDPhotoFrame(base64);

        // HANDLE QUOTA EXCEEDED (429) - Stop automatic polling PERMANENTLY
        if (result.feedback === 'AI_LIMIT') {
            if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
            setAiLimitReached(true); // Permanent Lock
            setValidationStatus('valid'); // Enable capture button
            setFeedbackMessage('AI TẠM NGƯNG');
            setInstruction('Hết lượt AI. Chuyển sang chụp thủ công.');
            return;
        }

        if (!result.faceDetected) {
           setValidationStatus('searching');
           setFeedbackMessage('Không tìm thấy mặt');
           setInstruction('Di chuyển vào khung hình');
        } else if (result.isCompliant) {
           setValidationStatus('valid');
           setFeedbackMessage('ĐẠT CHUẨN');
           setInstruction(result.instruction || 'Giữ nguyên tư thế!');
        } else {
           setValidationStatus('adjusting');
           setFeedbackMessage(result.feedback || 'Cần điều chỉnh');
           setInstruction(result.instruction || 'Chỉnh lại tư thế');
        }
      }
    } catch (err) {
      console.error("AI check failed", err);
    } finally {
      isAnalyzingRef.current = false;
    }
  };

  const getDevices = async () => {
    try {
      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);
      const canon = videoDevices.find(d => d.label.toLowerCase().includes('canon') || d.label.toLowerCase().includes('eos'));
      if (canon) setSelectedDeviceId(canon.deviceId);
    } catch (err) {
      console.error("Error enumerating devices", err);
    }
  };

  const startCamera = async (deviceId?: string) => {
    stopCamera();
    try {
      const constraints: MediaStreamConstraints = {
        video: {
          deviceId: deviceId ? { exact: deviceId } : undefined,
          width: { ideal: 3840 }, // Try 4K first
          height: { ideal: 2160 },
        },
        audio: false
      };
      // Fallback to 1080p if 4K fails is handled by 'ideal' usually, but safe to wrap
      let mediaStream;
      try {
          mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      } catch (e) {
          mediaStream = await navigator.mediaDevices.getUserMedia({ 
             video: { 
                 deviceId: deviceId ? { exact: deviceId } : undefined,
                 width: { ideal: 1920 }, 
                 height: { ideal: 1080 } 
             } 
          });
      }

      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;
      setError('');
    } catch (err) {
      setError('Không thể truy cập camera. Kiểm tra kết nối.');
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const captureFrame = useCallback(async () => {
    setIsCapturing(true);

    // Play Shutter Sound
    if (shutterAudioRef.current) {
        shutterAudioRef.current.currentTime = 0;
        shutterAudioRef.current.play().catch(() => {});
    }

    if (!videoRef.current || !canvasRef.current) {
        setIsCapturing(false);
        return;
    }

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');

    // --- HIGH QUALITY CAPTURE STRATEGY ---
    // 1. Try ImageCapture API (Hardware Photo)
    // 2. Fallback to Video Snapshot (Software Crop)

    let sourceImage: HTMLImageElement | HTMLVideoElement = video;
    let sourceW = video.videoWidth;
    let sourceH = video.videoHeight;
    let isHighRes = false;

    if (stream) {
        const track = stream.getVideoTracks()[0];
        // Check if ImageCapture is supported (Modern Browsers)
        if (track && 'ImageCapture' in window) {
            try {
                // @ts-ignore - Experimental API
                const imageCapture = new ImageCapture(track);
                const blob = await imageCapture.takePhoto();
                // We create an HTMLImageElement from the high-res blob
                const highResImg = new Image();
                const blobUrl = URL.createObjectURL(blob);

                await new Promise((resolve) => {
                    highResImg.onload = resolve;
                    highResImg.src = blobUrl;
                });

                sourceImage = highResImg;
                sourceW = highResImg.width;
                sourceH = highResImg.height;
                isHighRes = true;

                console.log(`Captured High-Res: ${sourceW}x${sourceH}`);
            } catch (e) {
                console.warn("ImageCapture API failed, falling back to video snapshot", e);
            }
        }
    }

    if (context && sourceW > 0 && sourceH > 0) {
        // Recalculate crop based on actual source dimensions (which might be 4K now)
        const crop = getCropDimensions(sourceW, sourceH);

        canvas.width = crop.w;
        canvas.height = crop.h;

        // Mirror effect logic:
        // Selfies are usually mirrored. 
        // If we use HighRes Photo, it usually comes unmirrored.
        // We ALWAYS mirror to ensure consistency with what user saw on screen.
        context.translate(canvas.width, 0);
        context.scale(-1, 1); 

        // Draw the cropped area
        context.drawImage(sourceImage, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);

        const dataUrl = canvas.toDataURL('image/jpeg', 1.0); // Max Quality JPEG
        onCapture(dataUrl);
    }

    setIsCapturing(false);
  }, [onCapture, selectedSize, stream]);

  useEffect(() => {
    if (countdown === null) return;

    // Countdown Audio Logic
    if (countdown > 0) {
        speak(countdown.toString(), true); // Read numbers 3, 2, 1
