export default CameraCapture;

import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

const API_KEY = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey: API_KEY });

const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Missing', instruction: 'Ready', faceDetected: true };
  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: "Analyze ID photo compliance. Check face orientation, eyes, lighting. Output JSON." }
        ]
      },
      config: { responseMimeType: 'application/json', responseSchema: analysisSchema }
    });
    return JSON.parse(response.text || '{}');
  } catch (error) {
    return { isCompliant: true, status: 'VALID', feedback: 'Offline', instruction: 'Chụp thủ công', faceDetected: true };
  }
};

export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beauty: BeautySettings, 
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) throw new Error("API Key missing");
  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // 1. Background Instruction
  let bgPart = "KEEP ORIGINAL BACKGROUND.";
  if (bgType === BackgroundType.WHITE) bgPart = "REPLACE background with SOLID PURE WHITE (#FFFFFF).";
  else if (bgType === BackgroundType.BLUE) bgPart = "REPLACE background with SOLID ID BLUE (#2792ff).";
  else if (bgType === BackgroundType.GRAY) bgPart = "REPLACE background with SOLID NEUTRAL GRAY (#d1d5db).";

  // 2. Beauty/Biometric Instruction (STRICT)
  const beautyTasks = [];
  if (beauty.removeBlemishes) beautyTasks.push("Subtly remove temporary acne/blemishes ONLY.");
  if (beauty.smoothSkin > 0) beautyTasks.push(`Softly smooth skin texture at ${beauty.smoothSkin}% intensity.`);
  if (beauty.lipstickIntensity > 0) beautyTasks.push(`Apply ${beauty.lipstickColor} lip tint at ${beauty.lipstickIntensity}% intensity.`);
  if (beauty.eyebrowIntensity > 0) beautyTasks.push(`Subtly define eyebrows at ${beauty.eyebrowIntensity}% intensity.`);
  if (beauty.blushIntensity > 0) beautyTasks.push(`Apply natural blush at ${beauty.blushIntensity}% intensity.`);

  const beautyPart = beautyTasks.length > 0 ? beautyTasks.join(" ") : "No facial retouching needed.";

  // 3. Final Unified Prompt
  const prompt = `
    ROLE: Professional Biometric ID Photo Editor.
    TASK: Process the input photo with these EXACT specifications:

    1. BACKGROUND: ${bgPart}
    2. CLOTHING: ${clothingPrompt ? `Replace current outfit with: ${clothingPrompt}. Ensure seamless collar fit.` : "Keep original clothing."}
    3. BEAUTY: ${beautyPart}

    CRITICAL BIOMETRIC RULES (MANDATORY):
    - DO NOT change facial geometry, jawline, nose shape, or eye distance.
    - DO NOT remove or alter PERMANENT IDENTIFIERS: Moles (nốt ruồi), scars (sẹo), and birthmarks MUST BE PRESERVED.
    - DO NOT use AI filters that beautify by distorting the face.
    - Maintain 100% anatomical accuracy for ID documents.
    - The output must be a single flattened high-resolution image.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }, { text: prompt }]
      }
    });

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (!part) throw new Error("AI failed to return image data");
    return `data:image/jpeg;base64,${part.inlineData.data}`;
  } catch (error) {
    console.error("AI Processing Error:", error);
    throw error;
  }
};

