import React, { useRef, useState, useEffect, useCallback } from 'react';
import { PhotoSize } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [isAutoCapture, setIsAutoCapture] = useState(false);
  const [status, setStatus] = useState<'searching' | 'valid' | 'invalid'>('searching');
  const [instruction, setInstruction] = useState('Đang khởi động camera...');

  useEffect(() => {
    startCamera();
    return () => stream?.getTracks().forEach(t => t.stop());
  }, []);

  const startCamera = async () => {
    const s = await navigator.mediaDevices.getUserMedia({ video: { width: 1920, height: 1080 }, audio: false });
    setStream(s);
    if (videoRef.current) videoRef.current.srcObject = s;
    setInstruction('Vui lòng nhìn thẳng vào camera');
  };

  // AI Loop
  useEffect(() => {
    const interval = setInterval(async () => {
      if (!videoRef.current || countdown !== null) return;

      const canvas = document.createElement('canvas');
      canvas.width = 320; canvas.height = 240;
      const ctx = canvas.getContext('2d');
      ctx?.drawImage(videoRef.current, 0, 0, 320, 240);

      const result = await analyzeIDPhotoFrame(canvas.toDataURL('image/jpeg', 0.5));

      if (result.status === 'VALID') {
        setStatus('valid');
        setInstruction('Tư thế rất tốt!');
        if (isAutoCapture && countdown === null) setCountdown(3);
      } else {
        setStatus('invalid');
        setInstruction(result.instruction || 'Vui lòng điều chỉnh lại');
      }
    }, 3000);
    return () => clearInterval(interval);
  }, [isAutoCapture, countdown]);

  const handleCapture = () => {
    if (!videoRef.current || !canvasRef.current) return;
    const ctx = canvasRef.current.getContext('2d');
    canvasRef.current.width = videoRef.current.videoWidth;
    canvasRef.current.height = videoRef.current.videoHeight;
    ctx?.scale(-1, 1);
    ctx?.drawImage(videoRef.current, -canvasRef.current.width, 0);
    onCapture(canvasRef.current.toDataURL('image/jpeg', 1.0));
  };

  useEffect(() => {
    if (countdown === 0) { handleCapture(); setCountdown(null); }
    if (countdown && countdown > 0) {
      const t = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(t);
    }
  }, [countdown]);

  return (
    <div className="h-full w-full bg-black flex flex-col items-center justify-center relative">
      <div className="absolute top-8 z-30 flex flex-col items-center gap-2">
         <div className={`px-6 py-2 rounded-full font-black text-xs border-2 shadow-xl transition-all ${status === 'valid' ? 'bg-green-600 border-green-400 text-white' : 'bg-red-600 border-red-400 text-white'}`}>
            {status === 'valid' ? 'SẴN SÀNG' : 'CHƯA ĐẠT'}
         </div>
         <p className="text-white text-sm font-bold drop-shadow-md">{instruction}</p>
      </div>

      <div className="relative h-[70vh] aspect-[2/3] border-4 border-white/20 rounded-lg overflow-hidden">
        <video ref={videoRef} autoPlay playsInline className="absolute inset-0 w-full h-full object-cover transform -scale-x-100" />
        <div className="absolute inset-0 border-[60px] border-black/40 pointer-events-none" />
        {countdown !== null && (
          <div className="absolute inset-0 bg-black/40 flex items-center justify-center z-40">
            <span className="text-9xl font-black text-white animate-ping">{countdown}</span>
          </div>
        )}
      </div>

      <div className="absolute bottom-12 flex items-center gap-8">
        <button onClick={() => setIsAutoCapture(!isAutoCapture)} className={`flex flex-col items-center gap-1 ${isAutoCapture ? 'text-brand-500' : 'text-gray-500'}`}>
          <div className={`w-12 h-12 rounded-xl flex items-center justify-center border-2 ${isAutoCapture ? 'border-brand-500 bg-brand-50' : 'border-gray-600'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
          </div>
          <span className="text-[10px] font-bold">TỰ ĐỘNG</span>
        </button>

        <button onClick={() => setCountdown(3)} disabled={countdown !== null} className="w-20 h-20 bg-white rounded-full border-8 border-gray-300 shadow-2xl active:scale-90 transition-all flex items-center justify-center">
           <div className="w-12 h-12 bg-red-600 rounded-full" />
        </button>

        <div className="w-12" />
      </div>
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

