import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

const API_KEY = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey: API_KEY });

const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Missing', instruction: 'Ready', faceDetected: true };
  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: "Analyze ID photo compliance. Output JSON." }
        ]
      },
      config: { responseMimeType: 'application/json', responseSchema: analysisSchema }
    });
    return JSON.parse(response.text || '{}');
  } catch (error) {
    return { isCompliant: true, status: 'VALID', feedback: 'Offline', instruction: 'Chụp thủ công', faceDetected: true };
  }
};

export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beauty: BeautySettings, 
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) throw new Error("API Key missing");
  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Deterministic Intensity Logic
  const getTask = (label: string, intensity: number, action: string) => {
    if (intensity <= 0) return "";
    return `TASK ${label}: Apply ${action} with a factor of ${intensity}/100. `;
  };

  let bgPart = "BACKGROUND: KEEP ORIGINAL.";
  if (bgType === BackgroundType.WHITE) bgPart = "BACKGROUND: REPLACE with SOLID PURE WHITE (#FFFFFF).";
  else if (bgType === BackgroundType.BLUE) bgPart = "BACKGROUND: REPLACE with SOLID ID BLUE (#2792ff).";
  else if (bgType === BackgroundType.GRAY) bgPart = "BACKGROUND: REPLACE with SOLID NEUTRAL GRAY (#d1d5db).";

  const tasks = [
    getTask("Smooth", beauty.smoothSkin, "skin smoothing/pore reduction"),
    getTask("Lipstick", beauty.lipstickIntensity, `lip tint using color ${beauty.lipstickColor}`),
    getTask("Eyebrow", beauty.eyebrowIntensity, "eyebrow definition while keeping original shape"),
    getTask("Blush", beauty.blushIntensity, "subtle natural blush to cheeks"),
    getTask("Contour", beauty.contourIntensity, "subtle facial contouring for depth"),
    getTask("HairVolume", beauty.hairVolume || 0, "natural hair volume enhancement")
  ].filter(t => t !== "").join(" ");

  const prompt = `
    ROLE: Expert Biometric ID Photo Processor. 
    IMAGE: Professional ID capture.

    INSTRUCTIONS:
    1. ${bgPart}
    2. CLOTHING: ${clothingPrompt ? `REPLACE outfit with: ${clothingPrompt}. Match lighting and fit neckline perfectly.` : "KEEP ORIGINAL CLOTHING."}
    3. RETOUCHING: ${tasks || "NO RETOUCHING REQUIRED."}

    STRICT BIOMETRIC PRESERVATION (ZERO TOLERANCE):
    - NO FACIAL DEFORMATION: Do not slim the face, do not enlarge eyes, do not change the shape of the nose, mouth, or chin.
    - PRESERVE IDENTITY: Moles (nốt ruồi), birthmarks, and scars are MANDATORY to keep. Do not remove them.
    - NATURALISM: The result must look like a high-end studio photograph, not a digital filter. 
    - CONSISTENCY: Apply retouching exactly at the requested intensity levels.
    - OUTPUT: One high-resolution opaque image (JPEG/PNG). No alpha channel.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }, { text: prompt }]
      }
    });

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (!part) throw new Error("AI failed to return image data");
    return `data:image/jpeg;base64,${part.inlineData.data}`;
  } catch (error) {
    console.error("AI Processing Error:", error);
    throw error;
  }
};

