           <img src={originalImage} className="absolute inset-0 w-full h-full object-cover" alt="Before" />
           <img 
            src={processedUrl} 
            className="absolute inset-0 w-full h-full object-cover transition-opacity duration-700" 
            style={{filter: imageFilters, clipPath: viewMode === 'slider' ? `inset(0 ${100-sliderPosition}% 0 0)` : 'none'}} 
            alt="After" 
           />

           {viewMode === 'slider' && (
             <div 
              className="absolute inset-0 cursor-ew-resize group" 
              onMouseMove={(e) => {
                if (e.buttons === 1) {
                  const rect = e.currentTarget.getBoundingClientRect();
                  setSliderPosition(((e.clientX - rect.left) / rect.width) * 100);
                }
              }}
              onTouchMove={(e) => {
                const rect = e.currentTarget.getBoundingClientRect();
                const touch = e.touches[0];
                setSliderPosition(((touch.clientX - rect.left) / rect.width) * 100);
              }}
             >
                <div className="absolute top-0 bottom-0 w-0.5 bg-white shadow-xl z-10" style={{left: `${sliderPosition}%`}}>
                  <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-8 bg-white rounded-full shadow-2xl flex items-center justify-center border border-slate-200">
                    <svg className="w-4 h-4 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4"></path></svg>
                  </div>
                </div>
             </div>
           )}
        </div>

        <div className="mt-4 flex gap-8 text-[10px] font-black text-slate-400 uppercase tracking-widest">
           <span>Trang phục gốc</span>
           <span>Kết quả chỉnh sửa</span>
        </div>
      </div>

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(5px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.3s ease-out forwards;
        }
        .no-scrollbar::-webkit-scrollbar {
          display: none;
        }
        .no-scrollbar {
          -ms-overflow-style: none;
          scrollbar-width: none;
        }
      `}</style>
    </div>
  );
};

export default ImageEditor;

