        setSaveStatus(success ? '✔ Đã lưu Cloud' : '⚠️ Lỗi đồng bộ');
    } catch (e) {
        setSaveStatus('❌ Lỗi mạng');
    } finally {
        setIsSyncing(false);
        setTimeout(() => setSaveStatus(''), 3000);
    }
  };

  const inputClass = "w-full bg-slate-50 border border-slate-200 text-slate-700 font-bold text-xs rounded-xl p-3 focus:bg-white focus:ring-4 focus:ring-brand-500/10 focus:border-brand-500 outline-none transition-all";

